def maxMedian(nums, k):
    a = sorted(nums)
    half = a[len(a) // 2:]
    lo, hi = half[0], half[0] + k
    while lo < hi:
        mid = (lo + hi + 1) // 2
        cost = 0
        for x in half:
            if x >= mid:
                break
            cost += mid - x
            if cost > k:
                break
        if cost <= k:
            lo = mid
        else:
            hi = mid - 1
    return lo
